from httpbin.core import app
client = app.test_client()

def test_patch_with_query_string_reflects_args_field():
    r = client.patch('/patch?foo=bar&baz=qux')
    assert r.status_code == 200
    body = r.get_json()
    assert body['args'] == {'foo': 'bar', 'baz': 'qux'}
    assert body['form'] == {}
    assert body['json'] is None

test_patch_with_query_string_reflects_args_field()

from httpbin.core import app
client = app.test_client()

def test_patch_response_headers_field_is_dict_with_host():
    r = client.patch(
        '/patch',
        headers={'X-Test-Header': 'sentinel'}
    )
    assert r.status_code == 200
    body = r.get_json()
    assert isinstance(body['headers'], dict)
    headers_lower = {k.lower(): v for k, v in body['headers'].items()}
    assert headers_lower.get('x-test-header') == 'sentinel'

test_patch_response_headers_field_is_dict_with_host()
